#!/bin/sh
# Embedded .ko - run: sh ./SCRIPT.sh (no separate .ko file needed)
set -e

# An argument can skip the interactive menu: 1/insmod or 2/ksud.
case "${1:-}" in
    1|insmod)
        LOAD_METHOD=insmod
        ;;
    2|ksud)
        LOAD_METHOD=ksud
        ;;
    "")
        echo '请选择内核模块加载方式：Telegram频道@ParadiseKMA'
        echo '  1) 普通 insmod'
        echo '  2) ksud insmod (KernelSU)'
        printf '请输入选项 [1/2]: '
        if ! IFS= read -r CHOICE; then
            echo '无法读取输入，请通过命令行参数指定 1 或 2。' >&2
            exit 2
        fi
        case "$CHOICE" in
            1) LOAD_METHOD=insmod ;;
            2) LOAD_METHOD=ksud ;;
            *) echo '无效选项，请输入 1 或 2。' >&2; exit 2 ;;
        esac
        ;;
    *)
        echo '参数无效，用法：sh SCRIPT.sh [1|2|insmod|ksud]' >&2
        exit 2
        ;;
esac

# Locate ksud only when this method is selected.
if [ "$LOAD_METHOD" = ksud ]; then
    if command -v ksud >/dev/null 2>&1; then
        KSUD_BIN=$(command -v ksud)
    elif [ -x /data/adb/ksud ]; then
        KSUD_BIN=/data/adb/ksud
    elif [ -x /data/adb/ksu/bin/ksud ]; then
        KSUD_BIN=/data/adb/ksu/bin/ksud
    else
        echo '未找到 ksud，请确认已安装支持 insmod 子命令的 KernelSU。' >&2
        exit 1
    fi
fi

TMP=$(mktemp)
trap 'rm -f "$TMP"' 0
trap 'exit 130' INT
trap 'exit 143' TERM

base64 -d <<'__EMBEDDED_KO_B64__' > "$TMP"
